-- 0552_dgg220_copy_marketing.sql
-- DGG-220 · Copy de marketing de alto impacto para los 7 mails de captación
-- (brief + 7 copywriters + dirección creativa, §6/workflow). Banners pro
-- regenerados con los nuevos títulos (public/email/dgg220-*.png; agenda ahora
-- con banner propio). Sólo actualiza asunto/cta/cuerpo_html_visual de las 7
-- plantillas captacion-*. TODO sigue GATED (flag OFF) — nada se envía.

UPDATE public.email_templates SET
  asunto = '{{nombre}}, llegá a la renovación sin apuro',
  cta_text = 'Quiero ver el curso',
  cta_url = 'https://gestionglobal.ar/formulario/curso-actualizacion?origen=prospecto',
  cuerpo_html_visual = $gg$<div style="display:none;max-height:0;overflow:hidden;opacity:0;mso-hide:all;">El único requisito académico de la renovación, a tu ritmo en el campus. El certificado oficial te queda listo.</div><img src="https://www.gestionglobal.ar/email/dgg220-curso-3190.png" alt="Curso de Actualización · FUNDPLATA · Gestión Global" width="576" style="display:block;width:100%;max-width:576px;height:auto;border-radius:12px;margin:2px 0 22px;" /><p style="margin:0 0 14px;">{{nombre}}, preferimos escribirte ahora y no sobre la hora. Tu matrícula vence el {{fecha_vencimiento}} y todavía te quedan {{dias_restantes}} días. No es un apuro: es tiempo de sobra para resolver con calma el único requisito académico de la renovación.</p><p style="margin:0 0 14px;">Ese requisito es el Curso de Actualización. Lo dicta FUNDPLATA y nosotros lo coordinamos académicamente. No es un curso de relleno: son contenidos teórico-prácticos pensados para administradores profesionales, que suman a tu gestión de todos los días.</p><p style="margin:0 0 16px;">Lo cursás en nuestro campus virtual, online y a tu ritmo, en los ratos que vos elijas. Cuando terminás, el certificado oficial te queda listo para presentar en la renovación.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 18px;background:#E7F1F9;border-left:4px solid #009ECA;border-radius:8px;"><tr><td style="padding:14px 16px;font-size:14.5px;line-height:1.6;color:#0B1F33;">Hacés el Curso de Actualización en el campus, a tu ritmo: lo empezás cuando quieras y avanzás en los ratos libres. Al terminar, el certificado oficial queda listo para tu renovación —sin turnos, sin filas, sin ir de ventanilla en ventanilla.</td></tr></table><p style="margin:0;">Adelantarte es sacarte el pendiente de encima antes de que apremie. Vos seguí administrando; del curso y los plazos nos ocupamos nosotros. Está todo listo para empezar cuando quieras —aliados de tu tiempo.</p>$gg$,
  updated_at = now()
WHERE slug = 'captacion-curso-3190';

UPDATE public.email_templates SET
  asunto = '{{nombre}}, estás a tiempo de renovar sin vueltas',
  cta_text = 'Empezar mi renovación',
  cta_url = 'https://gestionglobal.ar/formulario/curso-actualizacion?origen=prospecto',
  cuerpo_html_visual = $gg$<div style="display:none;max-height:0;overflow:hidden;opacity:0;mso-hide:all;">Los dos pasos que te mantienen habilitado, resueltos y acompañados desde un solo lugar.</div><img src="https://www.gestionglobal.ar/email/dgg220-curso-reno.png" alt="Curso + Renovación · FUNDPLATA · Gestión Global" width="576" style="display:block;width:100%;max-width:576px;height:auto;border-radius:12px;margin:2px 0 22px;" /><p style="margin:0 0 14px;">{{nombre}}, tu matrícula vence el {{fecha_vencimiento}}. Entrás en la recta final, y es justo ahí donde conviene que todo se vuelva simple. Estás a tiempo —y a tiempo de resolverlo sin vueltas.</p><p style="margin:0 0 14px;">Para seguir habilitado hay dos pasos: el curso de actualización y la renovación ante el RPAC. Los dos se resuelven desde un mismo lugar, a tu ritmo, sin saltar de ventanilla en ventanilla.</p><p style="margin:0 0 16px;">El curso es el Curso de Actualización de FUNDPLATA, coordinado académicamente por nosotros: campus virtual cómodo, contenidos a la altura de un profesional y certificado oficial al cierre. Con ese certificado en mano, gestionamos tu renovación ante la DPPJ y te mostramos en qué anda, paso a paso.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 18px;background:#E7F1F9;border-left:4px solid #009ECA;border-radius:8px;"><tr><td style="padding:14px 16px;font-size:14.5px;line-height:1.6;color:#0B1F33;">El Curso de Actualización lo dicta FUNDPLATA y te deja el certificado oficial listo para renovar. Lo cursás en el campus, a tu ritmo; del trámite ante el RPAC nos ocupamos nosotros.</td></tr></table><p style="margin:0;">Que la recta final sea la parte simple. Empezá hoy, a tu ritmo, y el resto del camino lo hacemos con vos. Así trabaja un aliado de tu tiempo.</p>$gg$,
  updated_at = now()
WHERE slug = 'captacion-curso-reno';

UPDATE public.email_templates SET
  asunto = '{{nombre}}, tu matrícula vencida tiene solución',
  cta_text = 'Quiero ponerla al día',
  cta_url = 'https://gestionglobal.ar/formulario/curso-actualizacion?origen=prospecto',
  cuerpo_html_visual = $gg$<div style="display:none;max-height:0;overflow:hidden;opacity:0;mso-hide:all;">El curso y la renovación, en un solo lugar. Vos empezás; del resto nos ocupamos.</div><img src="https://www.gestionglobal.ar/email/dgg220-vencida.png" alt="Volver a estar en regla · FUNDPLATA · Gestión Global" width="576" style="display:block;width:100%;max-width:576px;height:auto;border-radius:12px;margin:2px 0 22px;" /><p style="margin:0 0 14px;">Pasa, {{nombre}}. Entre tantos vencimientos, hay fechas que se corren solas. Tu matrícula venció el {{fecha_vencimiento}}, y con todo lo que llevás encima es de lo más entendible. Le pasa a muchos administradores.</p><p style="margin:0 0 14px;">La buena noticia es que tiene solución, y más simple de lo que parece. Para ponerte al día son dos pasos: el Curso de Actualización —lo dicta FUNDPLATA, lo coordinamos nosotros— y la renovación de tu matrícula ante el RPAC. Los dos, desde un mismo lugar.</p><p style="margin:0 0 16px;">Hacés el curso a tu ritmo en el campus, el certificado oficial te queda listo y nosotros gestionamos el trámite ante la DPPJ. Sin ir de ventanilla en ventanilla, sin llevar la cuenta de cada papel. Vos empezás; del orden nos ocupamos nosotros.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 18px;background:#E7F1F9;border-left:4px solid #009ECA;border-radius:8px;"><tr><td style="padding:14px 16px;font-size:14.5px;line-height:1.6;color:#0B1F33;">Curso, certificado y trámite de renovación: ordenados de principio a fin, en un solo lugar. Vos das el primer paso; del seguimiento ante el RPAC nos ocupamos nosotros.</td></tr></table><p style="margin:0;">Dar el primer paso hoy es empezar a sacártelo de encima, sin apuro y a tu ritmo. Cuando quieras, arrancamos juntos —aliados de tu tiempo, también cuando el tiempo se pasó.</p>$gg$,
  updated_at = now()
WHERE slug = 'captacion-vencida';

UPDATE public.email_templates SET
  asunto = 'Capacitate como el profesional que sos',
  cta_text = 'Quiero conocer el campus',
  cta_url = 'https://gestionglobal.ar/?origen=prospecto',
  cuerpo_html_visual = $gg$<div style="display:none;max-height:0;overflow:hidden;opacity:0;mso-hide:all;">Formación teórico-práctica, 100% online y a tu ritmo. El certificado oficial, al terminar.</div><img src="https://www.gestionglobal.ar/email/dgg220-campus.png" alt="Campus Virtual · Gestión Global" width="576" style="display:block;width:100%;max-width:576px;height:auto;border-radius:12px;margin:2px 0 22px;" /><p style="margin:0 0 14px;">El oficio cambió, {{nombre}}. La normativa se mueve, los consorcios preguntan más y el que se destaca es siempre el que va un paso adelante. Lo vivís todos los días.</p><p style="margin:0 0 14px;">Capacitarte no es un trámite más para tachar de la lista: es la forma más directa de elevar tu práctica y diferenciarte. Por eso existe el Campus Virtual de Gestión Global —formación teórico-práctica pensada a la medida del administrador, con la profundidad que el oficio pide.</p><p style="margin:0 0 16px;">Es 100% online y lo hacés a tu ritmo, cuando te queda cómodo. Lo armamos de igual a igual, porque conocemos el oficio desde adentro: es el nuestro.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 18px;background:#E7F1F9;border-left:4px solid #009ECA;border-radius:8px;"><tr><td style="padding:14px 16px;font-size:14.5px;line-height:1.6;color:#0B1F33;">Al terminar cada capacitación recibís tu certificado oficial: un respaldo concreto que suma a tu trayectoria y que tus consorcios valoran. Las herramientas las ponemos nosotros; el diferencial lo ponés vos.</td></tr></table><p style="margin:0;">Date una vuelta por el campus y mirá con qué podés formarte este año. El tiempo que invertís en vos vuelve en prestigio; de ordenarte el resto nos ocupamos nosotros —aliados de tu tiempo, también del que dedicás a crecer.</p>$gg$,
  updated_at = now()
WHERE slug = 'captacion-campus';

UPDATE public.email_templates SET
  asunto = '{{nombre}}, que ningún vencimiento te agarre de sorpresa',
  cta_text = 'Quiero mi agenda al día',
  cta_url = 'https://gestionglobal.ar/?origen=prospecto',
  cuerpo_html_visual = $gg$<div style="display:none;max-height:0;overflow:hidden;opacity:0;mso-hide:all;">Renovación, DDJJ y curso: cada fecha clave cargada y avisada a tiempo. Vos, a administrar.</div><img src="https://www.gestionglobal.ar/email/dgg220-agenda.png" alt="Agenda de vencimientos · Gestión Global" width="576" style="display:block;width:100%;max-width:576px;height:auto;border-radius:12px;margin:2px 0 22px;" /><p style="margin:0 0 14px;">Un vencimiento casi nunca avisa cuando se acerca, {{nombre}}. Avisa cuando ya pasó —y ahí resolverlo cuesta el doble.</p><p style="margin:0 0 14px;">No es falta de orden. Es que nadie debería llevar en la cabeza la renovación de la matrícula, la DDJJ anual y el curso, además de los consorcios, las reuniones y el teléfono que no para. La memoria es un mal lugar para guardar lo que no podés dejar pasar.</p><p style="margin:0 0 16px;">Por eso armamos algo simple: cargás tus fechas profesionales una sola vez y las seguimos por vos. Quedan ordenadas en un solo lugar, y te avisamos con tiempo —por mail, en tu portal y por teléfono— mucho antes de que apremie.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 18px;background:#E7F1F9;border-left:4px solid #009ECA;border-radius:8px;"><tr><td style="padding:14px 16px;font-size:14.5px;line-height:1.6;color:#0B1F33;">Tu agenda personalizada de vencimientos: renovación de matrícula, DDJJ anual y curso de actualización. Cada fecha cargada, ordenada y con recordatorios automáticos por mail, portal y teléfono. Vos la mirás cuando querés; el aviso llega siempre a tiempo.</td></tr></table><p style="margin:0;">Estar al día no debería costarte una sola noche de insomnio. Dejanos las fechas y quedate con lo que solo vos podés hacer: administrar. Del resto nos ocupamos nosotros —aliados de tu tiempo, lo cuidamos como lo cuidás vos.</p>$gg$,
  updated_at = now()
WHERE slug = 'captacion-agenda';

UPDATE public.email_templates SET
  asunto = '{{nombre}}, enterate cómo va tu trámite sin llamar a nadie',
  cta_text = 'Conocer el portal',
  cta_url = 'https://gestionglobal.ar/?origen=prospecto',
  cuerpo_html_visual = $gg$<div style="display:none;max-height:0;overflow:hidden;opacity:0;mso-hide:all;">En qué etapa está, qué falta y un aviso cuando se mueve. Sin perseguir a nadie.</div><img src="https://www.gestionglobal.ar/email/dgg220-tramites.png" alt="Seguimiento de trámites · Gestión Global" width="576" style="display:block;width:100%;max-width:576px;height:auto;border-radius:12px;margin:2px 0 22px;" /><p style="margin:0 0 14px;">Sabés cómo es, {{nombre}}. Presentás un trámite y arranca una segunda tarea que nadie te cobra pero igual te ocupa: llamar para preguntar cómo va, mandar un mail y esperar, anotar en un papel en qué quedó. El trámite avanza; la incertidumbre te la quedás vos.</p><p style="margin:0 0 14px;">No tendría que ser así. Saber en qué anda una gestión no debería depender de un llamado, ni de la buena memoria de nadie, ni de tu propia cabeza —que ya está bastante llena.</p><p style="margin:0 0 16px;">Por eso, en Gestión Global, cada trámite tuyo vive en el portal: con el estado al instante y siempre a la vista.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 18px;background:#E7F1F9;border-left:4px solid #009ECA;border-radius:8px;"><tr><td style="padding:14px 16px;font-size:14.5px;line-height:1.6;color:#0B1F33;">Desde una sola pantalla ves cada gestión en tiempo real: en qué etapa está, qué paso falta y cómo avanza. Y cuando algo se mueve o necesita una acción tuya, te avisamos —sin que tengas que preguntar.</td></tr></table><p style="margin:0;">Renovación, DDJJ, certificados y trámites: todo a la vista y en orden, sin perseguir a nadie. Vos administrás; del seguimiento nos ocupamos nosotros —aliados de tu tiempo, también en esto. Date una vuelta por el portal y mirá cómo se ve por dentro.</p>$gg$,
  updated_at = now()
WHERE slug = 'captacion-tramites';

UPDATE public.email_templates SET
  asunto = 'Crecer no debería costarte tiempo ni plata',
  cta_text = 'Quiero sumarme',
  cta_url = 'https://gestionglobal.ar/?origen=prospecto',
  cuerpo_html_visual = $gg$<div style="display:none;max-height:0;overflow:hidden;opacity:0;mso-hide:all;">Webinars y charlas para administradores: novedades, buenas prácticas y comunidad. Sin costo.</div><img src="https://www.gestionglobal.ar/email/dgg220-capacitaciones.png" alt="Capacitaciones gratuitas · Gestión Global" width="576" style="display:block;width:100%;max-width:576px;height:auto;border-radius:12px;margin:2px 0 22px;" /><p style="margin:0 0 14px;">Hola {{nombre}}. Mantenerte al día es parte de ejercer bien, y las ganas casi nunca faltan. Lo que falta es tiempo. Y, a veces, lo que cuesta una buena capacitación.</p><p style="margin:0 0 14px;">Por eso abrimos las nuestras. Webinars y charlas pensadas para administradores —novedades normativas, buenas prácticas, herramientas del día a día— de parte de gente que conoce el oficio porque es el suyo. Sin vueltas y sin costo.</p><p style="margin:0 0 16px;">No es un curso más para sumar a la lista. Es la forma más simple de estar al día y, de paso, encontrarte con colegas que están en la misma.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 18px;background:#E7F1F9;border-left:4px solid #009ECA;border-radius:8px;"><tr><td style="padding:14px 16px;font-size:14.5px;line-height:1.6;color:#0B1F33;">Acceso libre a nuestras capacitaciones y webinars para administradores: novedades normativas, buenas prácticas y herramientas del oficio. Sin costo y sin letra chica —más una comunidad que se actualiza junta.</td></tr></table><p style="margin:0;">No tenés que cambiar nada de lo que ya hacés: solo sumarte y empezar a aprovecharlo. Estar a la altura del oficio no debería costarte tiempo ni plata. De eso se tratan los aliados de tu tiempo.</p>$gg$,
  updated_at = now()
WHERE slug = 'captacion-capacitaciones';
